ZO_CreateStringId("NEXTTRYULTIMATETRACKER_ENABLED_TOOLTIP", "Enables or disables the entire addon. When disabled, no alerts are shown and no sounds are played.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_ONLY_COMBAT_TOOLTIP", "Shows the alert only in combat. If an Ultimate becomes ready outside combat, the alert appears when combat starts.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_TEST_MODE_TOOLTIP", "Keeps the box and screen text visible for testing position and appearance. This only bypasses normal combat and Ultimate logic for preview purposes.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_TARGET_BARS_TOOLTIP", "Selects which normal bar is watched for the Ultimate alert. Example: watch the back-bar Ultimate on a DD when the front-bar Ultimate is only slotted for passive bonuses. In Werewolf form, this is ignored and the addon uses Werewolf Fury tracking.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_BOX_SHOW_TOOLTIP", "Shows the blinking box while the alert is active.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_BOX_UNLOCK_TOOLTIP", "Makes the box movable. Lock it again after positioning to avoid moving it accidentally in combat.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_BLINK_SPEED_TOOLTIP", "Controls how fast the box blinks. Lower values blink faster.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_DRAW_LAYER_TOOLTIP", "Sets the broad UI layer of the box. Change this only if the box is hidden behind other UI elements or appears too far in front.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_DRAW_LEVEL_TOOLTIP", "Fine-tunes the draw order within the selected UI layer.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_DRAW_TIER_TOOLTIP", "Adds another display priority level. Higher values can help if other UI elements cover the box.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_TEXT_SHOW_TOOLTIP", "Shows screen text in addition to the box.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_TEXT_MODE_TOOLTIP", "Controls whether a short notice, the Ultimate name, or detailed information is shown.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_TEXT_UNLOCK_TOOLTIP", "Makes the screen text movable. Lock it again after positioning.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_TEXT_BG_ALPHA_TOOLTIP", "Controls how visible the background behind the screen text is.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_WEREWOLF_BLOCK_REVERT_TOOLTIP", "Blocks Werewolf revert in combat while the Werewolf Fury action is not detected as usable. The Werewolf Fury action itself should not be blocked.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_WEREWOLF_BLOCK_MESSAGE_TOOLTIP", "Shows a chat message when Werewolf revert was blocked.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_WEREWOLF_BLOCK_SOUND_TOOLTIP", "Also plays a short error sound when Werewolf revert was blocked.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_SOUND_ENABLED_TOOLTIP", "Plays a sound when an alert becomes active.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_SOUND_TOOLTIP", "Chooses the sound used for the Ultimate alert.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_TEST_SOUND_TOOLTIP", "Plays the current alert sound for testing.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_DEBUG_TOOLTIP", "Enables additional diagnostic chat messages. Use only for testing or troubleshooting.")

ZO_CreateStringId("NEXTTRYULTIMATETRACKER_ZONE_FILTER", "Zone Filter")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_ZONE_FILTER_ENABLED", "Use zone filter")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_ZONE_FILTER_ENABLED_TOOLTIP", "Controls whether only the alert output is filtered by the current area. This suppresses the blinking box, screen text and alert sound only. Ultimate locks and Werewolf revert protection remain active. Overland and cities are disabled by default when LibZone is available.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_ZONE_FILTER_LIBZONE_NOTE", "The zone filter requires optional LibZone. Without LibZone, the addon behaves as before and allows alert output in all areas. Ultimate locks and Werewolf revert protection are not affected by this filter.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_ZONE_FILTER_OVERLAND", "Show in overland / cities")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_ZONE_FILTER_OVERLAND_TOOLTIP", "Shows Ultimate alerts in open-world zones and cities. Disabled by default because this is often distracting while travelling.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_ZONE_FILTER_DELVE_PUBLIC", "Show in delves and public dungeons")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_ZONE_FILTER_DELVE_PUBLIC_TOOLTIP", "Shows Ultimate alerts in delves and public dungeons.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_ZONE_FILTER_DUNGEON_TRIAL", "Show in group dungeons and trials")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_ZONE_FILTER_DUNGEON_TRIAL_TOOLTIP", "Shows Ultimate alert output in group dungeons and trials. These areas share one option because LibZone may not always distinguish them consistently.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_ZONE_FILTER_ARENA", "Show in arenas")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_ZONE_FILTER_ARENA_TOOLTIP", "Shows Ultimate alerts in solo and group arenas.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_ZONE_FILTER_ENDLESS_ARCHIVE", "Show in Endless Archive")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_ZONE_FILTER_ENDLESS_ARCHIVE_TOOLTIP", "Shows Ultimate alerts in the Endless Archive.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_ZONE_FILTER_PVP", "Show in PvP areas")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_ZONE_FILTER_PVP_TOOLTIP", "Shows Ultimate alerts in Cyrodiil, Imperial City and Battlegrounds.")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_ZONE_FILTER_HOUSING", "Show in player housing")
ZO_CreateStringId("NEXTTRYULTIMATETRACKER_ZONE_FILTER_HOUSING_TOOLTIP", "Shows Ultimate alerts in player homes, useful for target dummy practice.")

